CreditValueByMonth = {
	init: async function (app, container) { 
		var query = "B2B/Credit/StatsByCalendarMonth(SystemId='" + app.Config.B2B.TransactionSource + "')";
		var data = await api.get(query);
		data.value = data.value.sort(function(a,b) { return new Date(b.CalendarMonth + "-01") - new Date(a.CalendarMonth + "-01"); });
		data.value.reverse();
		CreditValueByMonth.initTransactionValuesChart(container, data.value, app.Config.B2B.Currencies);
	},

	initTransactionValuesChart: function(container, data, currencies) {
		var categories = data.map(i => i.CalendarMonth).filter(function (value, index, self) { return self.indexOf(value) === index;});
		console.log({ component: "InvoiceValueByMonth", data: data });
		var args = {
			showLegend: true,
			categoryTemplate: "#: kendo.toString(value, type.dateFormat)#",
			valueTemplate: "#: kendo.toString(value, type.aggregateMoneyFormat)#",
			tooltipTemplate: "#= series.name #: #= kendo.toString(value, type.aggregateMoneyFormat) #",
			series: currencies.map(cur => {
				return { 
					name: "[resource_displayname[GrossValue]] (" + cur + ")", 
					data: categories.map(c => data.filter(i => i.Currency == cur && i.CalendarMonth == c).map(i => Math.round(Math.abs(i.Sum)))) 
					};
			}),
			categories: categories,
			max: data.map(i =>  Math.round(Math.abs(i.Sum))).sort(function(a,b){return b - a})[0],
			type: "column"
		};
		var chart = new Chart($("[name=transactionValue]", container), args);
		chart.init();
		return chart;
	}
};
